// مهارة: javascript-coding
// توليد قائمة شاملة من الهاشتاجات المستهدفة
const baseHashtags = [
  // أساسية
  '#عمرة_البدل', '#حج_البدل', '#نيابة_عن_الميت', '#عمرة_عن_الميت',
  '#عمرة_للمريض', '#حج_للمريض', '#بدل_عمرة', '#بدل_حج',
  // موسمية
  '#رمضان_قادم', '#عمرة_رمضان', '#حج_هذا_العام', '#موسم_الحج',
  #أشتاق_للبيت', '#البيت_العتيق', '#مكة_المكرمة', '#المدينة_المنورة',
  // عالمية (عربي)
  '#عمرة_امريكا', '#عمرة_كندا', '#عمرة_بريطانيا', '#عمرة_فرنسا',
  '#عمرة_اندونيسيا', '#عمرة_ماليزيا', '#عمرة_باكستان', '#عمرة_الهند',
  '#عمرة_تركيا', '#عمرة_الجزائر', '#عمرة_المغرب', '#عمرة_مصر',
  // إنجليزي
  '#UmrahProxy', '#HajjProxy', '#UmrahForDeceased', '#HajjForParents',
  '#UmrahOnBehalf', '#IslamicServices', '#MuslimCommunity',
  #UrduHashtags: '#umarah_badal', '#hajj_badal', '#waledain_ke_liye',
  #Indonesian: '#umrahbadal', '#hajibadal', '#almarhum'
];

// إنشاء مجموعات مركبة
const combinations = [];
baseHashtags.forEach(tag => {
  combinations.push({ hashtags: [tag], focus: 'single' });
});

// مجموعات ثنائية لزيادة الدقة
for (let i = 0; i < baseHashtags.length; i++) {
  for (let j = i + 1; j < baseHashtags.length; j++) {
    if (Math.random() > 0.7) { // عشوائية لتقليل العدد
      combinations.push({ 
        hashtags: [baseHashtags[i], baseHashtags[j]], 
        focus: 'combo' 
      });
    }
  }
}

return combinations.slice(0, 50).map(c => ({ json: c }));

// مهارة: data-processing
// استخراج وتحليل التعليقات للكشف عن النوايا
const items = $input.all();
const leads = [];

for (const item of items) {
  const post = item.json;
  const comments = post.comments || [];

  // تحليل كل تعليق
  comments.forEach(comment => {
    const text = comment.text.toLowerCase();
    const keywords = ['كيف', 'سعر', 'تسجيل', 'حجز', 'متوفي', 'مريض', 'والدي', 'والدتي', 'how much', 'register', 'book', 'deceased', 'mother', 'father'];

    if (keywords.some(k => text.includes(k))) {
      leads.push({
        json: {
          platform: 'instagram',
          post_url: post.url,
          post_hashtags: post.hashtags,
          author: comment.username,
          comment_text: comment.text,
          timestamp: comment.timestamp,
          context: 'comment_intent',
          location_tag: post.location || ''
        }
      });
    }
  });

  // تحليل المنشور نفسه أيضاً
  const caption = post.caption || '';
  if (caption.toLowerCase().includes('أبحث') || caption.toLowerCase().includes('أريد') || caption.includes('looking for')) {
    leads.push({
      json: {
        platform: 'instagram',
        post_url: post.url,
        author: post.author,
        comment_text: caption,
        timestamp: post.timestamp,
        context: 'post_intent',
        location_tag: post.location || ''
      }
    });
  }
}

return leads;
